#!/usr/bin/env python3
# version 0.1.0
"""Track the image files under container/src in a committed text file.

.gitignore leaves the images out of git, so git never shows them, and a
worktree or the OpenCode container holds none of them. This script writes
container/docs/image-files.txt, a small file that is committed instead:

    # Image files under container/src: sha1, size in bytes, path relative to container/src.
    # Generated by container/tools/images/image_list.py; do not edit by hand.
    <sha1>  <size>  <path>

One line per image file on disk, tracked or not, sorted by path in byte
order. An image is a regular file whose extension (any letter case) is
jpg jpeg png gif webp svg ico bmp avif tif tiff; symlinks are skipped. A
path may hold spaces, so a reader splits a line on whitespace at most
twice. The list shows in git which images the site has and when they
changed, a backup or the hosting copy can be checked against it, and
tests/test_img_src.py counts a listed image as present in a checkout that
has no images.

Usage (any working directory):
  python3 container/tools/images/image_list.py --write    # regenerate the list
  python3 container/tools/images/image_list.py --check    # 1 when the list is stale
  python3 container/tools/images/image_list.py --hook     # pre-commit gate

--src DIR scans another tree, --out FILE writes another list, --cache FILE
keeps the local sha1 cache (container/reports/, git-ignored). Hashing every
image of a big site on every commit is too slow, so a file whose size and
mtime_ns match its cache entry reuses the cached sha1; --no-cache hashes
everything.

--hook works like --write and exits 1 when the file changed, so the commit
stops and the new list can be staged. In a checkout without the images (a
worktree, the OpenCode container) fewer than half of the listed paths exist
on disk: --hook prints one line saying so and exits 0 without writing.

Exit codes: 0 fine, 1 the list changed or is stale, 2 bad arguments.
"""

from __future__ import annotations

import argparse
import hashlib
import os
import sys
import tempfile
from dataclasses import dataclass
from pathlib import Path

CONTAINER = Path(__file__).resolve().parents[2]

# The defaults: container/src is the tree, container/docs holds the list and
# container/reports is git-ignored scratch space for the cache.
DEFAULT_SRC = CONTAINER / "src"
DEFAULT_OUT = CONTAINER / "docs" / "image-files.txt"
DEFAULT_CACHE = CONTAINER / "reports" / "image-list-cache.tsv"

# The extensions .gitignore drops, in any letter case.
EXTENSIONS = frozenset({"jpg", "jpeg", "png", "gif", "webp", "svg", "ico", "bmp", "avif", "tif", "tiff"})

HEADER = "# Image files under container/src: sha1, size in bytes, path relative to container/src.\n# Generated by container/tools/images/image_list.py; do not edit by hand.\n"

MAX_SHOWN = 20  # paths per category in the summary


@dataclass(frozen=True)
class Image:
    """What the list records about one file: its sha1 and its size in bytes."""

    sha1: str
    size: int


def _is_image_name(name: str) -> bool:
    """True when a file name ends in one of the image extensions, any case."""
    return "." in name and name.rsplit(".", 1)[-1].lower() in EXTENSIONS


def scan(src: Path) -> list[tuple[str, int, int, Path]]:
    """(path relative to src, size, mtime_ns, file) per image, in byte order.

    os.scandir is used instead of Path.rglob: tens of thousands of images
    must stay a second-scale job, and scandir reads the type of an entry
    from the directory itself. Symlinks (to a file or a folder) are not
    listed.
    """
    found: list[tuple[str, int, int, Path]] = []
    stack = [(str(src), "")]
    while stack:
        directory, prefix = stack.pop()
        with os.scandir(directory) as entries:
            for entry in entries:
                rel = prefix + entry.name
                if entry.is_symlink():
                    continue
                if entry.is_dir(follow_symlinks=False):
                    stack.append((entry.path, rel + "/"))
                elif _is_image_name(entry.name) and entry.is_file(follow_symlinks=False):
                    stat = entry.stat(follow_symlinks=False)
                    found.append((rel, stat.st_size, stat.st_mtime_ns, Path(entry.path)))
    found.sort(key=lambda item: item[0].encode("utf-8"))
    return found


def sha1_of(path: Path) -> str:
    """The SHA-1 of a file; file_digest reads in chunks, so a large image stays cheap."""
    with path.open("rb") as handle:
        return hashlib.file_digest(handle, "sha1").hexdigest()


CacheKey = tuple[int, int]  # size, mtime_ns
Cache = dict[str, tuple[int, int, str]]  # path relative to src -> size, mtime_ns, sha1


def load_cache(path: Path) -> Cache:
    """The cache file as a dict; a missing or damaged file is an empty cache."""
    cache: Cache = {}
    if not path.is_file():
        return cache
    for line in path.read_text(encoding="utf-8").splitlines():
        if not line or line.startswith("#"):
            continue
        fields = line.split("\t")
        if len(fields) != 4 or not fields[3]:
            continue
        try:
            cache[fields[0]] = (int(fields[1]), int(fields[2]), fields[3])
        except ValueError:
            continue
    return cache


def render_cache(entries: dict[str, Image], stats: dict[str, CacheKey]) -> str:
    """The cache file text: path, size, mtime_ns, sha1, one file per line."""
    lines = ["# path\tsize\tmtime_ns\tsha1\n"]
    for rel in sorted(entries, key=lambda item: item.encode("utf-8")):
        size, mtime_ns = stats[rel]
        lines.append(f"{rel}\t{size}\t{mtime_ns}\t{entries[rel].sha1}\n")
    return "".join(lines)


def collect(src: Path, cache: Cache | None) -> tuple[dict[str, Image], dict[str, CacheKey]]:
    """Every image under src with its size and sha1, plus the stat keys for the cache."""
    entries: dict[str, Image] = {}
    stats: dict[str, CacheKey] = {}
    for rel, size, mtime_ns, path in scan(src):
        stats[rel] = (size, mtime_ns)
        hit = cache.get(rel) if cache is not None else None
        sha1 = hit[2] if hit is not None and hit[0] == size and hit[1] == mtime_ns else sha1_of(path)
        entries[rel] = Image(sha1, size)
    return entries, stats


def render(entries: dict[str, Image]) -> str:
    """The list file text: the header, then one sha1, size and path per line."""
    lines = [HEADER]
    for rel in sorted(entries, key=lambda item: item.encode("utf-8")):
        lines.append(f"{entries[rel].sha1}  {entries[rel].size}  {rel}\n")
    return "".join(lines)


def parse_list(text: str) -> dict[str, Image]:
    """The entries of a list file text; comments, blank and damaged lines are skipped."""
    entries: dict[str, Image] = {}
    for line in text.splitlines():
        if not line or line.startswith("#"):
            continue
        fields = line.split(maxsplit=2)  # a path may hold spaces
        if len(fields) != 3:
            continue
        try:
            entries[fields[2]] = Image(fields[0], int(fields[1]))
        except ValueError:
            continue
    return entries


def load_list(path: Path) -> dict[str, Image]:
    """The entries of the list file; a missing file is an empty list."""
    return parse_list(path.read_text(encoding="utf-8")) if path.is_file() else {}


def relate(old: dict[str, Image], new: dict[str, Image]) -> tuple[list[str], list[str], list[str]]:
    """(added, removed, changed) paths, sorted, between the list and the disk."""
    added = sorted(new.keys() - old.keys(), key=lambda item: item.encode("utf-8"))
    removed = sorted(old.keys() - new.keys(), key=lambda item: item.encode("utf-8"))
    changed = sorted((rel for rel in new.keys() & old.keys() if new[rel] != old[rel]), key=lambda item: item.encode("utf-8"))
    return added, removed, changed


def _show(label: str, paths: list[str]) -> None:
    """One summary line: the first MAX_SHOWN paths of a category."""
    more = f", ... ({len(paths) - MAX_SHOWN} more)" if len(paths) > MAX_SHOWN else ""
    print(f"  {label}: {', '.join(paths[:MAX_SHOWN])}{more}")


def report(out: Path, entries: dict[str, Image], differs: bool, old: dict[str, Image]) -> None:
    """Print the summary: the file count, then what changed and, in short, where."""
    print(f"{out}: {len(entries)} image(s) on disk")
    if not differs:
        print("  unchanged")
        return
    added, removed, changed = relate(old, entries)
    print(f"  {len(added)} added, {len(removed)} removed, {len(changed)} changed")
    for label, paths in (("added", added), ("removed", removed), ("changed", changed)):
        if paths:
            _show(label, paths)
    if not (added or removed or changed):
        print("  the text differs only in order or header")


def write_atomic(path: Path, text: str) -> None:
    """Write `text` to a temp file next to `path`, then rename it into place."""
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp = tempfile.mkstemp(dir=path.parent, prefix=f".{path.name}.", suffix=".tmp")
    try:
        with os.fdopen(fd, "w", encoding="utf-8", newline="\n") as handle:
            handle.write(text)
        os.chmod(tmp, 0o664)  # mkstemp creates 0600
        os.replace(tmp, path)
    finally:
        Path(tmp).unlink(missing_ok=True)  # gone already when the rename worked


def lacks_images(out: Path, src: Path) -> tuple[bool, str]:
    """True when this checkout lacks the images.

    The list names the files of a full checkout. When fewer than half of
    them exist here (a worktree, the OpenCode container), regenerating the
    list would drop the rest, so --hook leaves it alone.
    """
    listed = load_list(out)
    if not listed:
        return False, ""
    present = sum(1 for rel in listed if (src / rel).is_file())
    if present * 2 >= len(listed):
        return False, ""
    return True, (f"{out}: this checkout holds {present} of {len(listed)} listed images, so it has no images; the list is left alone")


def _parse_args(argv: list[str]) -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        prog="image_list.py",
        description="Write or check the tracked list of the image files under container/src.",
    )
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument("--write", action="store_true", help="regenerate the list")
    mode.add_argument("--check", action="store_true", help="exit 1 when the list is stale, never write")
    mode.add_argument("--hook", action="store_true", help="pre-commit: write, exit 1 when the file changed")
    parser.add_argument("--src", type=Path, default=DEFAULT_SRC, metavar="DIR", help="scanned tree (default: container/src)")
    parser.add_argument("--out", type=Path, default=DEFAULT_OUT, metavar="FILE", help="list file (default: container/docs/image-files.txt)")
    parser.add_argument("--cache", type=Path, default=DEFAULT_CACHE, metavar="FILE", help="sha1 cache (default: container/reports/image-list-cache.tsv)")
    parser.add_argument("--no-cache", action="store_true", help="hash every file, ignore and keep no cache")
    return parser.parse_args(argv)


def main(argv: list[str] | None = None) -> int:
    args = _parse_args(sys.argv[1:] if argv is None else argv)
    src: Path = args.src
    out: Path = args.out
    if not src.is_dir():
        print(f"error: {src} is not a directory", file=sys.stderr)
        return 2
    if args.hook:
        lacks, message = lacks_images(out, src)
        if lacks:
            print(message)
            return 0
    cache_path: Path | None = None if args.no_cache else args.cache
    cache = load_cache(cache_path) if cache_path is not None else None
    entries, stats = collect(src, cache)
    text = render(entries)
    differs = not out.is_file() or out.read_text(encoding="utf-8") != text
    report(out, entries, differs, load_list(out))
    if args.check:
        if differs:
            print("--check: the list is stale, run --write to regenerate it")
            return 1
        return 0
    if differs:
        write_atomic(out, text)
        print(f"wrote {out}")
    if cache_path is not None:
        write_atomic(cache_path, render_cache(entries, stats))
    return 1 if args.hook and differs else 0


if __name__ == "__main__":
    sys.exit(main())
